namespace Nafasyar;
public class SerialService(Database database){
 object Present(Dictionary<string,object?> r)=>new{id=r["id"],productId=r["product_id"],day=r["day"],created=r["created"],data=JsonNode.Parse((string)r["payload"]!)};
 public object List(Actor a,string id,string day){a.Require("device");using var db=database.Open();if(id!=""){var r=db.One("SELECT * FROM serial_runs WHERE id=?",id)??throw new ApiError("نوبت پیدا نشد.",404);return new{run=Present(r),serials=db.All("SELECT s.serial,r.id AS deviceId FROM serial_reservations s LEFT JOIN records r ON r.id='device:'||s.serial AND r.kind='device' WHERE s.run_id=? ORDER BY s.serial",id)};}if(day=="")day=J.Day();J.Jalali(day);return new{runs=db.All("SELECT * FROM serial_runs WHERE day=? ORDER BY created DESC,id LIMIT 200",day).Select(Present),day};}
 public object Create(Actor a,JsonNode b){a.Require("device","write");a.Require("product");var id=J.Text(b,"requestId");var product=J.Text(b,"productId");if(!Guid.TryParse(id,out _)||b["count"] is not JsonValue v||!v.TryGetValue<int>(out var count)||count is <1 or >100)throw new ApiError("تعداد صحیح ۱ تا ۱۰۰ و شناسه درخواست لازم است.");using var db=database.Open();return db.Atomic(()=>{var old=db.One("SELECT * FROM serial_runs WHERE id=?",id);if(old!=null){if((string)old["actor"]! !=a.UserId||(string)old["product_id"]! !=product||JsonNode.Parse((string)old["payload"]!)!["count"]!.GetValue<int>()!=count)throw new ApiError("شناسه برای درخواست دیگری استفاده شده است.",409);return (object)new{run=Present(old),replayed=true};}
 var p=db.Record(product);if(p?.Kind!="product"||p.Data.Text("status")!="فعال")throw new ApiError("محصول فعال انتخاب کنید.");var day=J.Day();var prefix=p.Data["code"]+"-"+J.Jalali(day)+"-";var existing=db.All("SELECT serial FROM serial_reservations WHERE serial>=? AND serial<? UNION ALL SELECT substr(id,8) AS serial FROM records WHERE id>=? AND id<? AND kind='device'",prefix,prefix+'\uffff',"device:"+prefix,"device:"+prefix+'\uffff');long last=0;foreach(var row in existing){var code=(string)row["serial"]!;if(code.StartsWith(prefix)&&J.Match(code[prefix.Length..],@"^\d{4,}$")&&long.TryParse(code[prefix.Length..],out var n))last=Math.Max(last,n);}if(last+count>99999999)throw new ApiError("ظرفیت شماره روز تکمیل است.");var data=new{name=p.Data.Text("name"),model=p.Data.Text("model"),code=p.Data["code"],count, @operator=a.Name,jalaliDate=J.Jalali(day,true)};var now=J.Now();db.Exec("INSERT INTO serial_runs(id,product_id,actor,day,payload,created) VALUES(?,?,?,?,?,?)",id,product,a.UserId,day,J.Write(data),now);for(int i=1;i<=count;i++)db.Exec("INSERT INTO serial_reservations VALUES(?,?,?)",prefix+(last+i).ToString("0000"),id,product);db.Audit(a,id,"reserve_device_serials",new{productId=product,count,first=prefix+(last+1).ToString("0000"),last=prefix+(last+count).ToString("0000")});return new{run=Present(db.One("SELECT * FROM serial_runs WHERE id=?",id)!)};});}
 public string Print(Actor a,string id,bool thermal){a.Require("device");using var db=database.Open();var run=db.One("SELECT * FROM serial_runs WHERE id=?",id)??throw new ApiError("نوبت پیدا نشد.",404);var p=JsonNode.Parse((string)run["payload"]!)!;var labels=db.All("SELECT serial FROM serial_reservations WHERE run_id=? ORDER BY serial",id).Select(r=>$"<article><img src='/brand/nafasyar-logo.png' alt='نفس‌یار'><div>{J.Esc(J.Text(p,"name"))} · {J.Esc(J.Text(p,"model"))}</div><strong dir='ltr'>{J.Esc((string)r["serial"]!)}</strong><small>تخصیص: {J.Esc(J.Text(p,"jalaliDate"))} · با من نفس بکش</small></article>");return "<!doctype html><html lang='fa' dir='rtl'><meta charset='utf-8'><title>چاپ سریال</title><style>body{font:14px Tahoma;margin:0;background:#eee}header{padding:20px}section{display:grid;grid-template-columns:"+(thermal?"60mm":"repeat(3,62mm)")+";gap:"+(thermal?"0":"2mm")+";margin:20px auto;width:max-content}article{box-sizing:border-box;width:"+(thermal?"60mm":"62mm")+";height:30mm;padding:2mm;background:white;display:flex;flex-direction:column;align-items:center;justify-content:space-between;break-inside:avoid;overflow:hidden;font-size:8pt}img{width:18mm;height:9mm;object-fit:contain}strong{font:700 "+(J.Text(p,"code").Length>25?"6":"9")+"pt monospace;overflow-wrap:anywhere;max-width:100%;text-align:center}small{font-size:7pt}@page{size:"+(thermal?"60mm 30mm":"A4")+";margin:"+(thermal?"0":"8mm")+"}@media print{header{display:none}body{background:white}section{margin:0;"+(thermal?"display:block":"")+"}article{"+(thermal?"break-after:page":"")+"}article:last-child{break-after:auto}}</style><header><button onclick='window.print()'>چاپ / ذخیره PDF</button><p>اندازه چاپ ۱۰۰٪؛ سربرگ و پابرگ مرورگر خاموش. ابتدا یک صفحه آزمایشی چاپ کنید.</p></header><section>"+string.Concat(labels)+"</section></html>";}
}
